// DepotLoadMeasure: the exact region bytes a wire buffer will need, and it is
// ONE SCAN — a record's type id gives its storage size, its length gives the
// next record — reading no field value at all, so the caller owns the
// allocation and can refuse a number it did not expect (§6.5).
//
// It reports the DATA bytes and the ATTRIBUTION bytes separately, because the
// attribution is the wire's numbering made resident (§6.3) and a caller may
// release it once Load returns. The answer is their sum.
inline int64_t DepotLoadMeasure( const uint8_t * wire_file, int64_t wire_file_bytes, int64_t * attribution_bytes = NULL, TableRefuseReason * reason_out = NULL )
{
    TableReport ignored;
    TableIdTable ids_table;
    int64_t body_bytes = 0;
    // a FORM BYTE this build does not carry is refused by name (§3, §6.5);
    // a trailer that cannot be read whole is damage and names no reason
    const TableOpenVerdict verdict = TableOpen( wire_file, wire_file_bytes, ids_table, body_bytes );
    if ( verdict == TableOpenRefused ) { if ( reason_out != NULL ) { *reason_out = unknown_form; } return -1; }
    if ( verdict != TableOpenOk ) { return -1; }
    // ANY BYTE BETWEEN THE ROOT'S TERMINATOR AND THE TABLE'S FIRST ENTRY
    // IS MALFORMED (docs/SPEC-TABLES.md §3): the two ends of the file have
    // met, nothing is decoded, and no region is sized from it.
    if ( TableBodyEndsEarly( wire_file + 1, body_bytes, ids_table ) ) { return -1; }
    const uint8_t * const wire = wire_file + 1;
    const int64_t wire_bytes = body_bytes;
    TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &ignored, &ids_table );
    TableRefuseReason reason = count_over_length;
    int64_t data = TableAlignUp64( (int64_t) sizeof( Depot ) );
    int64_t records = 0;
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    while ( TableNodeScanNext( scan, type_id, body, length ) )
    {
        records++;
        int64_t storage = DepotNodeStorage( type_id, length, reason );
        if ( storage == kTableNodeRefused ) { if ( reason_out != NULL ) { *reason_out = reason; } return -1; } // an N the record's framing cannot carry, or a blob past the cap (§2.8, §2.9, §3.1)
        if ( storage > 0 ) { data += storage; } // a type id this build cannot name commands none
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( attribution_bytes != NULL ) { *attribution_bytes = attribution; }
    return data + attribution;
}

// DepotLoad: decode the tolerant wire into the caller's exact-sized region and
// return the root. LOAD IS A SCAN, and that is the whole of its bound: it
// follows no reference, so there is no depth cap, no visited set and no
// ordering rule on the indices. Partial results are kept, as everywhere on
// this wire — the report says what happened. NULL means the CALLER's buffer
// was wrong.
inline const Depot * DepotLoad( uint8_t * region, int64_t region_bytes, const uint8_t * wire_file, int64_t wire_file_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    // THE FORM BYTE IS READ FIRST, then the trailer, and only then a body:
    // a file that is both a newer form and damaged is a REFUSAL and never
    // damage (docs/SPEC-TABLES.md §3).
    TableIdTable ids_table;
    int64_t body_bytes = 0;
    const TableOpenVerdict verdict = TableOpen( wire_file, wire_file_bytes, ids_table, body_bytes );
    if ( verdict != TableOpenOk )
    {
        if ( verdict == TableOpenDamaged ) { out->malformed = true; } else { out->refused = true; if ( wire_file_bytes > 0 && wire_file[0] == kTableWireMessageForm ) { out->reason = message_form_as_file; } else { out->reason = newer_form; } }
        return NULL;
    }
    if ( TableBodyEndsEarly( wire_file + 1, body_bytes, ids_table ) )
    {
        out->malformed = true; // a byte no field claims, before the table (§3)
        return NULL;
    }
    const uint8_t * const wire = wire_file + 1;
    const int64_t wire_bytes = body_bytes;
    if ( region == NULL || region_bytes < (int64_t) sizeof( Depot ) ) { out->malformed = true; return NULL; }
    if ( ( ( (uintptr_t) region ) & ( kTableAlign - 1 ) ) != 0 ) { out->malformed = true; return NULL; }
    memset( region, 0, (size_t) region_bytes );
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;

    // the record count and the data bytes, from the FRAMING alone
    TableRefuseReason reason = count_over_length; // LoadMeasure is where a caller reads it; a Load past a refusal is malformed
    int64_t data = TableAlignUp64( (int64_t) sizeof( Depot ) );
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting, &ids_table );
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            records++;
            int64_t storage = DepotNodeStorage( type_id, length, reason );
            if ( storage == kTableNodeRefused ) { out->malformed = true; return NULL; }
            if ( storage > 0 ) { data += storage; }
        }
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( data + attribution > region_bytes ) { out->malformed = true; return NULL; }

    TableNodeMap nodes;
    nodes.base = region;
    nodes.entries = (const TableNodeDirEntry *) ( region + data );
    nodes.count = records + 1;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) ( region + data );
    directory[0].offset = 0; // position 0 is the ROOT, at offset 0 (§6.3)
    directory[0].type_id = 0x327fe6dc702553fdull;
    Depot * root = new ( region ) Depot; // lifetime only: LoadBody's first act is DepotReset
    DepotReset( *root );

    // PASS ONE: fill the numbering from the framing, so that an index
    // resolves whichever way it points. It reads no body.
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t used = TableAlignUp64( (int64_t) sizeof( Depot ) );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            int64_t storage = DepotNodeStorage( type_id, length, reason );
            if ( storage <= 0 )
            {
                // a record whose type id this build cannot name KEEPS ITS
                // INDEX, is counted once here and not once per pointer, and
                // every reference to it reads null (§3.1)
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
                directory[k + 1].type_id = type_id;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) used;
                directory[k + 1].type_id = type_id;
                DepotNodePlace( type_id, region + used, length );
                used += storage;
            }
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        // the table is whole or it is nothing: a scan that failed counts
        // malformed and NOT the unknowns it met on the way, because the
        // numbering they belonged to does not exist (§3.1)
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }

    // PASS TWO: decode each body into its own storage. A forward index
    // resolves without scratch, because pass one already placed every node.
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out, &ids_table );
                DepotNodeBody( type_id, sub, nodes, region + directory[k + 1].offset );
            }
            k++;
        }
    }

    // and the ROOT's own body last, so every index it carries resolves
    // against a numbering already known good or already known bad
    TableReader r( wire, wire_bytes, out, &ids_table );
    r.nested = false; // the ROOT body, the one that carries the node table
    DepotLoadBody( r, nodes, *root );
    return root;
}

// DepotLoadMeasure: the exact region bytes a wire buffer will need, and it is
// ONE SCAN — a record's type id gives its storage size, its length gives the
// next record — reading no field value at all, so the caller owns the
// allocation and can refuse a number it did not expect (§6.5).
//
// It reports the DATA bytes and the ATTRIBUTION bytes separately, because the
// attribution is the wire's numbering made resident (§6.3) and a caller may
// release it once Load returns. The answer is their sum.
inline int64_t DepotLoadMeasure( const TableVocabulary & vocabulary, const uint8_t * message, int64_t message_bytes, int64_t * attribution_bytes = NULL, TableRefuseReason * reason_out = NULL )
{
    TableReport ignored;
    // a FORM BYTE this build does not carry is refused by name (§3, §6.5); a
    // message with no announced table is the connection's refusal (§3.3)
    if ( message_bytes < 1 || !vocabulary.announced ) { return -1; }
    if ( message[0] != kTableWireMessageForm ) { if ( reason_out != NULL ) { *reason_out = unknown_form; } return -1; }
    const TableIdTable & ids_table = vocabulary.table;
    const uint8_t * const wire = message + 1;
    const int64_t wire_bytes = message_bytes - 1;
    TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &ignored, &ids_table );
    TableRefuseReason reason = count_over_length;
    int64_t data = TableAlignUp64( (int64_t) sizeof( Depot ) );
    int64_t records = 0;
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    while ( TableNodeScanNext( scan, type_id, body, length ) )
    {
        records++;
        int64_t storage = DepotNodeStorage( type_id, length, reason );
        if ( storage == kTableNodeRefused ) { if ( reason_out != NULL ) { *reason_out = reason; } return -1; } // an N the record's framing cannot carry, or a blob past the cap (§2.8, §2.9, §3.1)
        if ( storage > 0 ) { data += storage; } // a type id this build cannot name commands none
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( attribution_bytes != NULL ) { *attribution_bytes = attribution; }
    return data + attribution;
}

// DepotLoadMessage: decode the tolerant wire into the caller's exact-sized region and
// return the root. LOAD IS A SCAN, and that is the whole of its bound: it
// follows no reference, so there is no depth cap, no visited set and no
// ordering rule on the indices. Partial results are kept, as everywhere on
// this wire — the report says what happened. NULL means the CALLER's buffer
// was wrong.
inline const Depot * DepotLoadMessage( uint8_t * region, int64_t region_bytes, const TableVocabulary & vocabulary, const uint8_t * message, int64_t message_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    // THE FORM BYTE IS READ FIRST, and then the connection's own table:
    // a message with no table is REFUSED BY NAME, nothing is decoded, no
    // counter moves and malformed does not fire (docs/SPEC-TABLES.md §3.3).
    if ( message_bytes < 1 ) { out->malformed = true; return NULL; }
    if ( message[0] != kTableWireMessageForm ) { out->refused = true; out->reason = newer_form; return NULL; }
    if ( !vocabulary.announced ) { out->refused = true; out->reason = no_vocabulary; return NULL; }
    const TableIdTable & ids_table = vocabulary.table;
    const uint8_t * const wire = message + 1;
    const int64_t wire_bytes = message_bytes - 1;
    if ( region == NULL || region_bytes < (int64_t) sizeof( Depot ) ) { out->malformed = true; return NULL; }
    if ( ( ( (uintptr_t) region ) & ( kTableAlign - 1 ) ) != 0 ) { out->malformed = true; return NULL; }
    memset( region, 0, (size_t) region_bytes );
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;

    // the record count and the data bytes, from the FRAMING alone
    TableRefuseReason reason = count_over_length; // LoadMeasure is where a caller reads it; a Load past a refusal is malformed
    int64_t data = TableAlignUp64( (int64_t) sizeof( Depot ) );
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting, &ids_table );
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            records++;
            int64_t storage = DepotNodeStorage( type_id, length, reason );
            if ( storage == kTableNodeRefused ) { out->malformed = true; return NULL; }
            if ( storage > 0 ) { data += storage; }
        }
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( data + attribution > region_bytes ) { out->malformed = true; return NULL; }

    TableNodeMap nodes;
    nodes.base = region;
    nodes.entries = (const TableNodeDirEntry *) ( region + data );
    nodes.count = records + 1;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) ( region + data );
    directory[0].offset = 0; // position 0 is the ROOT, at offset 0 (§6.3)
    directory[0].type_id = 0x327fe6dc702553fdull;
    Depot * root = new ( region ) Depot; // lifetime only: LoadBody's first act is DepotReset
    DepotReset( *root );

    // PASS ONE: fill the numbering from the framing, so that an index
    // resolves whichever way it points. It reads no body.
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t used = TableAlignUp64( (int64_t) sizeof( Depot ) );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            int64_t storage = DepotNodeStorage( type_id, length, reason );
            if ( storage <= 0 )
            {
                // a record whose type id this build cannot name KEEPS ITS
                // INDEX, is counted once here and not once per pointer, and
                // every reference to it reads null (§3.1)
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
                directory[k + 1].type_id = type_id;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) used;
                directory[k + 1].type_id = type_id;
                DepotNodePlace( type_id, region + used, length );
                used += storage;
            }
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        // the table is whole or it is nothing: a scan that failed counts
        // malformed and NOT the unknowns it met on the way, because the
        // numbering they belonged to does not exist (§3.1)
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }

    // PASS TWO: decode each body into its own storage. A forward index
    // resolves without scratch, because pass one already placed every node.
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out, &ids_table );
                DepotNodeBody( type_id, sub, nodes, region + directory[k + 1].offset );
            }
            k++;
        }
    }

    // and the ROOT's own body last, so every index it carries resolves
    // against a numbering already known good or already known bad
    TableReader r( wire, wire_bytes, out, &ids_table );
    r.nested = false; // the ROOT body, the one that carries the node table
    DepotLoadBody( r, nodes, *root );
    return root;
}

// DepotLoadBuilder: the TOOL's path — the same tolerant decode into a fresh
// builder, so loaded data can be edited and locked again. The numbering is
// the same one; what differs is where a node lives and therefore what a
// resolved slot holds — an arena offset here, a self-relative delta there.
inline bool DepotLoadBuilder( DepotBuilder & builder, const uint8_t * wire_file, int64_t wire_file_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    TableIdTable ids_table;
    int64_t body_bytes = 0;
    const TableOpenVerdict verdict = TableOpen( wire_file, wire_file_bytes, ids_table, body_bytes );
    if ( verdict != TableOpenOk )
    {
        if ( verdict == TableOpenDamaged ) { out->malformed = true; } else { out->refused = true; }
        return false;
    }
    if ( TableBodyEndsEarly( wire_file + 1, body_bytes, ids_table ) )
    {
        out->malformed = true; // a byte no field claims, before the table (§3)
        return false;
    }
    const uint8_t * const wire = wire_file + 1;
    const int64_t wire_bytes = body_bytes;
    Depot * root = builder.GetRoot();
    if ( root == NULL ) { out->malformed = true; return false; }
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting, &ids_table );
        while ( TableNodeScanNext( scan, type_id, body, length ) ) { records++; }
    }
    // the AUTHORING side may allocate (§6.5), and this is the tool's path.
    // It goes through the builder's own pair, like everything else the
    // builder reaches, and the entries come back zeroed.
    const TableAllocator allocator = builder.arena.allocator;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) allocator.alloc( allocator.context, ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry ) );
    if ( directory == NULL ) { out->malformed = true; return false; }
    directory[0].offset = (uint64_t) builder.root_ref.value;
    directory[0].type_id = 0x327fe6dc702553fdull;
    TableNodeMap nodes;
    nodes.base = NULL;
    nodes.entries = directory;
    nodes.count = records + 1;
    nodes.arena = true; // a resolved slot holds the node's ARENA OFFSET here
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            uint32_t at = DepotNodeAlloc( type_id, builder.main, length );
            if ( at == 0 )
            {
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) at;
            }
            directory[k + 1].type_id = type_id;
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out, &ids_table );
                DepotNodeBody( type_id, sub, nodes, TableArenaAt( builder.arena, (uint32_t) directory[k + 1].offset ) );
            }
            k++;
        }
    }
    TableReader r( wire, wire_bytes, out, &ids_table );
    r.nested = false; // the ROOT body, the one that carries the node table
    bool ok = DepotLoadBody( r, nodes, *root );
    allocator.free( allocator.context, directory );
    return ok;
}

// ---- Album: the variable-length life (docs/SPEC-TABLES.md §2, §6, §9) ----
//
// MUTABLE: AlbumBuilder — allocate nodes, wire them together, then Lock.
// CONST:   one packed region, root at its base. Lock produces it and Load
//          produces it, so a locked structure and a loaded one are the
//          SAME representation with one view API. There is no unlock:
//          re-editing means loading the const form into a fresh builder.
// Album is never held by value — a file-format-scale structure is a region
// and a root pointer, not a struct you copy.

struct AlbumBuilder
{
    TableArena arena;
    TableWorker main;      // the calling thread's allocation front
    TableRef root_ref;
    uint8_t * region = NULL; // the packed const form, produced by Lock()
    int64_t region_bytes = 0;

    // THE ALLOCATOR IS THE BUILDER'S, and everything this structure ever
    // allocates goes through it: the arena's segments, Lock's identity map,
    // the packed region, the wire walks' numbering, and the tool path's node
    // directory. Name your own and a profiler sees every byte under it.
    AlbumBuilder( TableAllocator allocator = TableDefaultAllocator() )
    {
        TableArenaInit( arena, allocator );
        main.arena = &arena;
        TableSlot<Album> slot = main.Alloc<Album>();
        root_ref = slot.ref;
    }
    ~AlbumBuilder() { TableArenaShutdown( arena ); arena.allocator.free( arena.allocator.context, region ); }
    AlbumBuilder( const AlbumBuilder & ) = delete;
    AlbumBuilder & operator=( const AlbumBuilder & ) = delete;

    // Alloc a node in THIS thread's slab: no lock, no atomic per node.
    // The result is usable both as the node pointer and as the reference
    // to store in a pointer field.
    template <typename T> TableSlot<T> Alloc() { return main.Alloc<T>(); }
    // a BYTE BUFFER's node of exactly `length` bytes (docs/SPEC-TABLES.md §2.5):
    // the bytes to write through, and the reference to store in a *bytes
    // or *string slot; a blob past a slab takes a span of its own
    TableBytesSlot AllocBytes( int64_t length ) { return main.AllocBytes( length ); }
    TableStringSlot AllocString( int64_t length ) { return main.AllocString( length ); }
    // one worker per thread; allocate on your own, and synchronize your own
    // writes to nodes another worker allocated
    TableWorker Worker() { TableWorker worker; worker.arena = &arena; return worker; }

    // GetRoot/AsConst, not Root/Const: a member function hides the type
    // name it shares, and `table Root` is this spec's own canonical
    // example. The checker refuses a table named after any member here,
    // so the remaining spellings cannot collide either.
    Album * GetRoot() { return arena.locked ? NULL : (Album *) TableArenaAt( arena, (uint32_t) root_ref.value ); }
    bool Locked() const { return arena.locked; }
    const Album * AsConst() const { return (const Album *) region; }
    const uint8_t * Region() const { return region; }
    int64_t RegionBytes() const { return region_bytes; }

    // Lock is ONE WAY and it is the compaction: the segmented arena becomes
    // one exact-packed region with zero slack, references rewritten
    // self-relative, and the mutable life released. Single-threaded: call
    // it after the workers have joined.
    bool Lock();
};

inline bool AlbumBuilder::Lock()
{
    if ( arena.locked ) { return region != NULL; }
    if ( root_ref.null() ) { return false; }
    TableArenaCtx ctx = { &arena };
    const Album & root = *(const Album *) TableArenaAt( arena, (uint32_t) root_ref.value );
    // The ROOT takes the map's first entry: it is packed at offset 0, and its
    // descent is open for the whole walk (docs/SPEC-TABLES.md §3.1).
    TablePackMap seen;
    TablePackMapInit( seen, arena.allocator );
    bool root_taken = false;
    int64_t root_slot = 0;
    int64_t below = -1;
    if ( TablePackMapReach( seen, (const void *) &root, 0, root_taken, root_slot ) != NULL )
    {
        below = AlbumPackMeasure( ctx, seen, root );
    }
    if ( below < 0 ) { TablePackMapShutdown( seen ); return false; } // a data cycle, named at the reference that closes it
    int64_t total = TableAlignUp64( (int64_t) sizeof( Album ) ) + below;
    // the AUTHORING path may allocate (§6.5), and it does so through the
    // builder's own pair. The region comes back ZEROED, which is the
    // allocator's contract: a packed region carries node padding.
    uint8_t * packed = (uint8_t *) arena.allocator.alloc( arena.allocator.context, total );
    if ( packed == NULL ) { TablePackMapShutdown( seen ); return false; }
    int64_t used = TableAlignUp64( (int64_t) sizeof( Album ) );
    Album * destination = new ( packed ) Album; // lifetime only: the Pack below memcpy's the whole node over it
    // The pack walk RE-DERIVES the same numbering rather than carrying the
    // measure's — nothing passes between them, which is what makes
    // `used == total` below a real check and not a tautology (§3.1). The
    // map keeps the capacity the measure paid for, so the second walk
    // rehashes nothing.
    TablePackMapReset( seen );
    if ( TablePackMapReach( seen, (const void *) &root, 0, root_taken, root_slot ) == NULL ||
         !AlbumPack( ctx, seen, root, *destination, packed, total, used ) || used != total )
    {
        TablePackMapShutdown( seen );
        arena.allocator.free( arena.allocator.context, packed );
        return false;
    }
    TablePackMapShutdown( seen );
    region = packed;
    region_bytes = total;
    arena.locked = true; // MONOTONIC: there is no unlock
    TableArenaShutdown( arena );
    return true;
}

// ---- Album on the wire: the FLAT NODE TABLE (docs/SPEC-TABLES.md §3.1) ----
//
// A pointered save writes every reachable node ONCE, into a node table under
// the reserved id 0xFFFF, and a pointer field rides as a u32 INDEX into it
// under kind 17. No pointer edge is a nesting level, so a chain's length is
// not a depth and two references to one node are one node.

// AlbumNodeStorage: the region bytes one record commands, or -1 for a type id
// this build cannot name — which keeps its index and reads null. A BYTE
// BUFFER's record commands its header and its bytes (docs/SPEC-TABLES.md §2.5),
// which is the one answer the record's LENGTH decides, and a blob past the
// size cap answers kTableNodeRefused with its reason (§3.1, §6.5).
inline int64_t AlbumNodeStorage( uint64_t type_id, int64_t length, TableRefuseReason & reason )
{
    (void) length; // no byte buffer below this root: every node's storage is its type's
    switch ( type_id )
    {
        case 0x69ff34904242a73dull: return TableAlignUp64( (int64_t) sizeof( Tally ) ); // Tally
        case 0xd6458a3eef83d457ull: return TableAlignUp64( (int64_t) sizeof( Marker ) ); // Marker
        case 0xf60ec899a5a69fa9ull: return TableAlignUp64( (int64_t) sizeof( ListNode ) ); // ListNode
        default: break;
    }
    (void) reason; // no blob and no extent below this root: nothing here refuses
    return -1;
}

// AlbumNodePlace: start one record's node's lifetime in the storage pass one
// reserved for it, holding exactly the declared defaults — a byte buffer's
// header holds its length, and its bytes come in pass two.
inline void AlbumNodePlace( uint64_t type_id, uint8_t * at, int64_t length )
{
    (void) length;
    switch ( type_id )
    {
        case 0x69ff34904242a73dull: { Tally * node = new ( at ) Tally; TallyReset( *node ); break; } // Tally
        case 0xd6458a3eef83d457ull: { Marker * node = new ( at ) Marker; MarkerReset( *node ); break; } // Marker
        case 0xf60ec899a5a69fa9ull: { ListNode * node = new ( at ) ListNode; ListNodeReset( *node ); break; } // ListNode
        default: break;
    }
}

// AlbumNodeAlloc: the TOOL's path — one record's node in the builder's arena.
// Zero is the arena's null, and it is also what a type id this build cannot
// name answers.
inline uint32_t AlbumNodeAlloc( uint64_t type_id, TableWorker & worker, int64_t length )
{
    (void) length;
    switch ( type_id )
    {
        case 0x69ff34904242a73dull: return (uint32_t) worker.Alloc<Tally>().ref.value; // Tally
        case 0xd6458a3eef83d457ull: return (uint32_t) worker.Alloc<Marker>().ref.value; // Marker
        case 0xf60ec899a5a69fa9ull: return (uint32_t) worker.Alloc<ListNode>().ref.value; // ListNode
        default: break;
    }
    return 0;
}

// AlbumNodeBody: PASS TWO's half — decode one record's body into the storage it
// already owns.
inline void AlbumNodeBody( uint64_t type_id, TableReader & r, const TableNodeMap & nodes, uint8_t * at )
{
    switch ( type_id )
    {
        case 0x69ff34904242a73dull: TallyLoadBody( r, *(Tally *) at ); break; // Tally
        case 0xd6458a3eef83d457ull: MarkerLoadBody( r, nodes, *(Marker *) at ); break; // Marker
        case 0xf60ec899a5a69fa9ull: ListNodeLoadBody( r, nodes, *(ListNode *) at ); break; // ListNode
        default: break;
    }
}

// The numbering both wire walks derive, and NEITHER CARRIES THE OTHER'S: the
// root takes index 1 and its entry stays open for the whole walk, so a
// reference back at it is the cycle it is (§3.1).
template <typename Ctx>
inline bool AlbumNumberFrom( const Ctx & ctx, TableNumbering & numbering, const Album & root )
{
    bool taken = false;
    int64_t slot = 0;
    if ( TablePackMapReach( numbering.seen, (const void *) &root, (int64_t) kTableNodeIndexRoot, taken, slot ) == NULL ) { return false; }
    return AlbumNumber( ctx, numbering, root );
}

// `message` selects the MESSAGE FORM (docs/SPEC-TABLES.md §3.3): the same
// walk over the same graph, with every reference a compile-time SLOT of
// the connection's announced table and no trailer to write.
template <typename Ctx>
inline int64_t AlbumMeasureWire( const Ctx & ctx, const Album & root, TableAllocator allocator, bool message = false )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    int64_t bytes = -1;
    if ( AlbumNumberFrom( ctx, numbering, root ) )
    {
        TableIds ids;
        ids.vocabulary = message;
        bytes = AlbumMeasureBody( ctx, numbering, ids, root );
        if ( bytes >= 0 )
        {
            const int64_t table = TableNodeTableMeasure( ctx, ids, numbering );
            // the FORM BYTE, the ROOT BODY — its own fields, the node table
            // and the terminator — and the ID TABLE (docs/SPEC-TABLES.md §3)
            const int64_t trailer = message ? 0 : TableIdsBytes( ids );
            bytes = table < 0 || ids.overflow ? -1 : 1 + bytes + table + trailer;
        }
    }
    TableNumberingShutdown( numbering );
    return bytes;
}

template <typename Ctx>
inline int64_t AlbumSaveWire( const Ctx & ctx, const Album & root, uint8_t * buffer, int64_t capacity, TableAllocator allocator, bool message = false )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    if ( !AlbumNumberFrom( ctx, numbering, root ) ) { TableNumberingShutdown( numbering ); return -1; }
    TableWriter w( buffer, capacity );
    TableIds ids;
    ids.vocabulary = message;
    w.put8( message ? kTableWireMessageForm : kTableWireForm ); // the FORM BYTE is the whole header (§3)
    // the root's own fields, then the node table's field, then the
    // terminator: a reader that gives up inside the table has already
    // decoded the ROOT'S OWN FIELDS (§3.1)
    bool ok = AlbumSaveBodyFields( ctx, numbering, w, ids, root ) && TableNodeTableSave( ctx, w, ids, numbering );
    TableNumberingShutdown( numbering );
    if ( !ok || ids.overflow ) { return -1; }
    w.put8( 0 ); // the ZERO REFERENCE that ends the root body
    // A MESSAGE HAS NO TRAILER: its last byte is the body's terminator,
    // because the ids live in the connection's table (§3.3).
    if ( !message ) { TableIdsWrite( w, ids ); }
    if ( w.overflow ) { return -1; } // the caller's buffer was too small
    return w.offset; // == AlbumMeasure( root )
}

inline int64_t AlbumMeasure( const Album * root, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return AlbumMeasureWire( ctx, *root, allocator );
}

inline int64_t AlbumSave( const Album * root, uint8_t * buffer, int64_t capacity, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return AlbumSaveWire( ctx, *root, buffer, capacity, allocator );
}

inline int64_t AlbumMeasure( const AlbumBuilder & builder )
{
    if ( builder.region != NULL ) { return AlbumMeasure( builder.AsConst(), builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return AlbumMeasureWire( ctx, *(const Album *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), builder.arena.allocator );
}

inline int64_t AlbumSave( const AlbumBuilder & builder, uint8_t * buffer, int64_t capacity )
{
    if ( builder.region != NULL ) { return AlbumSave( builder.AsConst(), buffer, capacity, builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return AlbumSaveWire( ctx, *(const Album *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), buffer, capacity, builder.arena.allocator );
}

inline int64_t AlbumMeasureMessage( const Album * root, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return AlbumMeasureWire( ctx, *root, allocator, true );
}

inline int64_t AlbumSaveMessage( const Album * root, uint8_t * buffer, int64_t capacity, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return AlbumSaveWire( ctx, *root, buffer, capacity, allocator, true );
}

inline int64_t AlbumMeasureMessage( const AlbumBuilder & builder )
{
    if ( builder.region != NULL ) { return AlbumMeasureMessage( builder.AsConst(), builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; }
    TableArenaCtx ctx = { &builder.arena };
    return AlbumMeasureWire( ctx, *(const Album *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), builder.arena.allocator, true );
}

inline int64_t AlbumSaveMessage( const AlbumBuilder & builder, uint8_t * buffer, int64_t capacity )
{
    if ( builder.region != NULL ) { return AlbumSaveMessage( builder.AsConst(), buffer, capacity, builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; }
    TableArenaCtx ctx = { &builder.arena };
    return AlbumSaveWire( ctx, *(const Album *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), buffer, capacity, builder.arena.allocator, true );
}

// AlbumLoadMeasure: the exact region bytes a wire buffer will need, and it is
// ONE SCAN — a record's type id gives its storage size, its length gives the
// next record — reading no field value at all, so the caller owns the
// allocation and can refuse a number it did not expect (§6.5).
//
// It reports the DATA bytes and the ATTRIBUTION bytes separately, because the
// attribution is the wire's numbering made resident (§6.3) and a caller may
// release it once Load returns. The answer is their sum.
inline int64_t AlbumLoadMeasure( const uint8_t * wire_file, int64_t wire_file_bytes, int64_t * attribution_bytes = NULL, TableRefuseReason * reason_out = NULL )
{
    TableReport ignored;
    TableIdTable ids_table;
    int64_t body_bytes = 0;
    // a FORM BYTE this build does not carry is refused by name (§3, §6.5);
    // a trailer that cannot be read whole is damage and names no reason
    const TableOpenVerdict verdict = TableOpen( wire_file, wire_file_bytes, ids_table, body_bytes );
    if ( verdict == TableOpenRefused ) { if ( reason_out != NULL ) { *reason_out = unknown_form; } return -1; }
    if ( verdict != TableOpenOk ) { return -1; }
    // ANY BYTE BETWEEN THE ROOT'S TERMINATOR AND THE TABLE'S FIRST ENTRY
    // IS MALFORMED (docs/SPEC-TABLES.md §3): the two ends of the file have
    // met, nothing is decoded, and no region is sized from it.
    if ( TableBodyEndsEarly( wire_file + 1, body_bytes, ids_table ) ) { return -1; }
    const uint8_t * const wire = wire_file + 1;
    const int64_t wire_bytes = body_bytes;
    TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &ignored, &ids_table );
    TableRefuseReason reason = count_over_length;
    int64_t data = TableAlignUp64( (int64_t) sizeof( Album ) );
    int64_t records = 0;
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    while ( TableNodeScanNext( scan, type_id, body, length ) )
    {
        records++;
        int64_t storage = AlbumNodeStorage( type_id, length, reason );
        if ( storage == kTableNodeRefused ) { if ( reason_out != NULL ) { *reason_out = reason; } return -1; } // an N the record's framing cannot carry, or a blob past the cap (§2.8, §2.9, §3.1)
        if ( storage > 0 ) { data += storage; } // a type id this build cannot name commands none
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( attribution_bytes != NULL ) { *attribution_bytes = attribution; }
    return data + attribution;
}

// AlbumLoad: decode the tolerant wire into the caller's exact-sized region and
// return the root. LOAD IS A SCAN, and that is the whole of its bound: it
// follows no reference, so there is no depth cap, no visited set and no
// ordering rule on the indices. Partial results are kept, as everywhere on
// this wire — the report says what happened. NULL means the CALLER's buffer
// was wrong.
inline const Album * AlbumLoad( uint8_t * region, int64_t region_bytes, const uint8_t * wire_file, int64_t wire_file_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    // THE FORM BYTE IS READ FIRST, then the trailer, and only then a body:
    // a file that is both a newer form and damaged is a REFUSAL and never
    // damage (docs/SPEC-TABLES.md §3).
    TableIdTable ids_table;
    int64_t body_bytes = 0;
    const TableOpenVerdict verdict = TableOpen( wire_file, wire_file_bytes, ids_table, body_bytes );
    if ( verdict != TableOpenOk )
    {
        if ( verdict == TableOpenDamaged ) { out->malformed = true; } else { out->refused = true; if ( wire_file_bytes > 0 && wire_file[0] == kTableWireMessageForm ) { out->reason = message_form_as_file; } else { out->reason = newer_form; } }
        return NULL;
    }
    if ( TableBodyEndsEarly( wire_file + 1, body_bytes, ids_table ) )
    {
        out->malformed = true; // a byte no field claims, before the table (§3)
        return NULL;
    }
    const uint8_t * const wire = wire_file + 1;
    const int64_t wire_bytes = body_bytes;
    if ( region == NULL || region_bytes < (int64_t) sizeof( Album ) ) { out->malformed = true; return NULL; }
    if ( ( ( (uintptr_t) region ) & ( kTableAlign - 1 ) ) != 0 ) { out->malformed = true; return NULL; }
    memset( region, 0, (size_t) region_bytes );
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;

    // the record count and the data bytes, from the FRAMING alone
    TableRefuseReason reason = count_over_length; // LoadMeasure is where a caller reads it; a Load past a refusal is malformed
    int64_t data = TableAlignUp64( (int64_t) sizeof( Album ) );
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting, &ids_table );
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            records++;
            int64_t storage = AlbumNodeStorage( type_id, length, reason );
            if ( storage == kTableNodeRefused ) { out->malformed = true; return NULL; }
            if ( storage > 0 ) { data += storage; }
        }
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( data + attribution > region_bytes ) { out->malformed = true; return NULL; }

    TableNodeMap nodes;
    nodes.base = region;
    nodes.entries = (const TableNodeDirEntry *) ( region + data );
    nodes.count = records + 1;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) ( region + data );
    directory[0].offset = 0; // position 0 is the ROOT, at offset 0 (§6.3)
    directory[0].type_id = 0xd858c2cb7f1514ccull;
    Album * root = new ( region ) Album; // lifetime only: LoadBody's first act is AlbumReset
    AlbumReset( *root );

    // PASS ONE: fill the numbering from the framing, so that an index
    // resolves whichever way it points. It reads no body.
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t used = TableAlignUp64( (int64_t) sizeof( Album ) );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            int64_t storage = AlbumNodeStorage( type_id, length, reason );
            if ( storage <= 0 )
            {
                // a record whose type id this build cannot name KEEPS ITS
                // INDEX, is counted once here and not once per pointer, and
                // every reference to it reads null (§3.1)
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
                directory[k + 1].type_id = type_id;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) used;
                directory[k + 1].type_id = type_id;
                AlbumNodePlace( type_id, region + used, length );
                used += storage;
            }
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        // the table is whole or it is nothing: a scan that failed counts
        // malformed and NOT the unknowns it met on the way, because the
        // numbering they belonged to does not exist (§3.1)
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }

    // PASS TWO: decode each body into its own storage. A forward index
    // resolves without scratch, because pass one already placed every node.
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out, &ids_table );
                AlbumNodeBody( type_id, sub, nodes, region + directory[k + 1].offset );
            }
            k++;
        }
    }

    // and the ROOT's own body last, so every index it carries resolves
    // against a numbering already known good or already known bad
    TableReader r( wire, wire_bytes, out, &ids_table );
    r.nested = false; // the ROOT body, the one that carries the node table
    AlbumLoadBody( r, nodes, *root );
    return root;
}

// AlbumLoadMeasure: the exact region bytes a wire buffer will need, and it is
// ONE SCAN — a record's type id gives its storage size, its length gives the
// next record — reading no field value at all, so the caller owns the
// allocation and can refuse a number it did not expect (§6.5).
//
// It reports the DATA bytes and the ATTRIBUTION bytes separately, because the
// attribution is the wire's numbering made resident (§6.3) and a caller may
// release it once Load returns. The answer is their sum.
inline int64_t AlbumLoadMeasure( const TableVocabulary & vocabulary, const uint8_t * message, int64_t message_bytes, int64_t * attribution_bytes = NULL, TableRefuseReason * reason_out = NULL )
{
    TableReport ignored;
    // a FORM BYTE this build does not carry is refused by name (§3, §6.5); a
    // message with no announced table is the connection's refusal (§3.3)
    if ( message_bytes < 1 || !vocabulary.announced ) { return -1; }
    if ( message[0] != kTableWireMessageForm ) { if ( reason_out != NULL ) { *reason_out = unknown_form; } return -1; }
    const TableIdTable & ids_table = vocabulary.table;
    const uint8_t * const wire = message + 1;
    const int64_t wire_bytes = message_bytes - 1;
    TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &ignored, &ids_table );
    TableRefuseReason reason = count_over_length;
    int64_t data = TableAlignUp64( (int64_t) sizeof( Album ) );
    int64_t records = 0;
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    while ( TableNodeScanNext( scan, type_id, body, length ) )
    {
        records++;
        int64_t storage = AlbumNodeStorage( type_id, length, reason );
        if ( storage == kTableNodeRefused ) { if ( reason_out != NULL ) { *reason_out = reason; } return -1; } // an N the record's framing cannot carry, or a blob past the cap (§2.8, §2.9, §3.1)
        if ( storage > 0 ) { data += storage; } // a type id this build cannot name commands none
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( attribution_bytes != NULL ) { *attribution_bytes = attribution; }
    return data + attribution;
}

// AlbumLoadMessage: decode the tolerant wire into the caller's exact-sized region and
// return the root. LOAD IS A SCAN, and that is the whole of its bound: it
// follows no reference, so there is no depth cap, no visited set and no
// ordering rule on the indices. Partial results are kept, as everywhere on
// this wire — the report says what happened. NULL means the CALLER's buffer
// was wrong.
inline const Album * AlbumLoadMessage( uint8_t * region, int64_t region_bytes, const TableVocabulary & vocabulary, const uint8_t * message, int64_t message_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    // THE FORM BYTE IS READ FIRST, and then the connection's own table:
    // a message with no table is REFUSED BY NAME, nothing is decoded, no
    // counter moves and malformed does not fire (docs/SPEC-TABLES.md §3.3).
    if ( message_bytes < 1 ) { out->malformed = true; return NULL; }
    if ( message[0] != kTableWireMessageForm ) { out->refused = true; out->reason = newer_form; return NULL; }
    if ( !vocabulary.announced ) { out->refused = true; out->reason = no_vocabulary; return NULL; }
    const TableIdTable & ids_table = vocabulary.table;
    const uint8_t * const wire = message + 1;
    const int64_t wire_bytes = message_bytes - 1;
    if ( region == NULL || region_bytes < (int64_t) sizeof( Album ) ) { out->malformed = true; return NULL; }
    if ( ( ( (uintptr_t) region ) & ( kTableAlign - 1 ) ) != 0 ) { out->malformed = true; return NULL; }
    memset( region, 0, (size_t) region_bytes );
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;

    // the record count and the data bytes, from the FRAMING alone
    TableRefuseReason reason = count_over_length; // LoadMeasure is where a caller reads it; a Load past a refusal is malformed
    int64_t data = TableAlignUp64( (int64_t) sizeof( Album ) );
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting, &ids_table );
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            records++;
            int64_t storage = AlbumNodeStorage( type_id, length, reason );
            if ( storage == kTableNodeRefused ) { out->malformed = true; return NULL; }
            if ( storage > 0 ) { data += storage; }
        }
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( data + attribution > region_bytes ) { out->malformed = true; return NULL; }

    TableNodeMap nodes;
    nodes.base = region;
    nodes.entries = (const TableNodeDirEntry *) ( region + data );
    nodes.count = records + 1;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) ( region + data );
    directory[0].offset = 0; // position 0 is the ROOT, at offset 0 (§6.3)
    directory[0].type_id = 0xd858c2cb7f1514ccull;
    Album * root = new ( region ) Album; // lifetime only: LoadBody's first act is AlbumReset
    AlbumReset( *root );

    // PASS ONE: fill the numbering from the framing, so that an index
    // resolves whichever way it points. It reads no body.
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t used = TableAlignUp64( (int64_t) sizeof( Album ) );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            int64_t storage = AlbumNodeStorage( type_id, length, reason );
            if ( storage <= 0 )
            {
                // a record whose type id this build cannot name KEEPS ITS
                // INDEX, is counted once here and not once per pointer, and
                // every reference to it reads null (§3.1)
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
                directory[k + 1].type_id = type_id;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) used;
                directory[k + 1].type_id = type_id;
                AlbumNodePlace( type_id, region + used, length );
                used += storage;
            }
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        // the table is whole or it is nothing: a scan that failed counts
        // malformed and NOT the unknowns it met on the way, because the
        // numbering they belonged to does not exist (§3.1)
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }

    // PASS TWO: decode each body into its own storage. A forward index
    // resolves without scratch, because pass one already placed every node.
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out, &ids_table );
                AlbumNodeBody( type_id, sub, nodes, region + directory[k + 1].offset );
            }
            k++;
        }
    }

    // and the ROOT's own body last, so every index it carries resolves
    // against a numbering already known good or already known bad
    TableReader r( wire, wire_bytes, out, &ids_table );
    r.nested = false; // the ROOT body, the one that carries the node table
    AlbumLoadBody( r, nodes, *root );
    return root;
}

// AlbumLoadBuilder: the TOOL's path — the same tolerant decode into a fresh
// builder, so loaded data can be edited and locked again. The numbering is
// the same one; what differs is where a node lives and therefore what a
// resolved slot holds — an arena offset here, a self-relative delta there.
inline bool AlbumLoadBuilder( AlbumBuilder & builder, const uint8_t * wire_file, int64_t wire_file_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    TableIdTable ids_table;
    int64_t body_bytes = 0;
    const TableOpenVerdict verdict = TableOpen( wire_file, wire_file_bytes, ids_table, body_bytes );
    if ( verdict != TableOpenOk )
    {
        if ( verdict == TableOpenDamaged ) { out->malformed = true; } else { out->refused = true; }
        return false;
    }
    if ( TableBodyEndsEarly( wire_file + 1, body_bytes, ids_table ) )
    {
        out->malformed = true; // a byte no field claims, before the table (§3)
        return false;
    }
    const uint8_t * const wire = wire_file + 1;
    const int64_t wire_bytes = body_bytes;
    Album * root = builder.GetRoot();
    if ( root == NULL ) { out->malformed = true; return false; }
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting, &ids_table );
        while ( TableNodeScanNext( scan, type_id, body, length ) ) { records++; }
    }
    // the AUTHORING side may allocate (§6.5), and this is the tool's path.
    // It goes through the builder's own pair, like everything else the
    // builder reaches, and the entries come back zeroed.
    const TableAllocator allocator = builder.arena.allocator;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) allocator.alloc( allocator.context, ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry ) );
    if ( directory == NULL ) { out->malformed = true; return false; }
    directory[0].offset = (uint64_t) builder.root_ref.value;
    directory[0].type_id = 0xd858c2cb7f1514ccull;
    TableNodeMap nodes;
    nodes.base = NULL;
    nodes.entries = directory;
    nodes.count = records + 1;
    nodes.arena = true; // a resolved slot holds the node's ARENA OFFSET here
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            uint32_t at = AlbumNodeAlloc( type_id, builder.main, length );
            if ( at == 0 )
            {
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) at;
            }
            directory[k + 1].type_id = type_id;
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out, &ids_table );
                AlbumNodeBody( type_id, sub, nodes, TableArenaAt( builder.arena, (uint32_t) directory[k + 1].offset ) );
            }
            k++;
        }
    }
    TableReader r( wire, wire_bytes, out, &ids_table );
    r.nested = false; // the ROOT body, the one that carries the node table
    bool ok = AlbumLoadBody( r, nodes, *root );
    allocator.free( allocator.context, directory );
    return ok;
}

// ---- the cooked form: point at a cook (docs/SPEC-TABLES.md §7) ----

// MetaOpen: match the header and POINT. On a match the bytes ARE what this
// build wrote, in this build's layout and this build's byte order, so there
// is nothing to validate and nothing to fix up and the root comes back as it
// lies. On ANY refusal it returns NULL and NAMES the refusal in the caller's
// TableRefuseReason, the first failing clause in §7's order (a wrong build
// version is a re-cook, a foreign order a cross-endian cook, a truncated
// file a bad download, an unaligned base the caller's own buffer), and the
// caller falls back to a wire load, which is the path that carries every
// version. The reason is written on the refusal path only; a caller that
// passes nothing gets the null alone.
//
// It is O(1) IN THE FILE'S SIZE — the header and nothing per node — so a one
// megabyte cook and a one gigabyte cook open in the same time, and a mapped
// file's pages are touched only as they are used. That is a property of
// touching nothing at open rather than a separate mechanism.
//
// Meta IS FIXED-SIZE, so its cook is ONE REGION OF ONE NODE and not a second
// shape (§7): one struct behind the header, at the region's base, which is
// what this returns. There is no graph below it and nothing to resolve.
//
// There is ONE entry point and no tolerant twin: a build either wrote this
// file or it did not, and the build version is what says which. Validating a
// file whose provenance a person doubts is schema cook-check, offline,
// over the ATTRIBUTION part beside the data — a person's decision, never a
// parameter on a load.
inline const Meta * MetaOpen( const void * bytes, uint64_t length, TableRefuseReason * reason = NULL )
{
    return (const Meta *) TableCookOpen( bytes, length, (uint64_t) sizeof( Meta ), (uint64_t) alignof( Meta ), reason );
}

